name: Run tests on label

on:
  pull_request:
    types: [labeled]

jobs:
  run-tests:
    if: ${{ contains(github.event.pull_request.labels.*.name, 'run-tests') }}
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: Check if PR author is external
        id: check_external
        uses: actions/github-script@v6
        with:
          script: |
            const username = context.payload.pull_request.user.login;
            const org = context.repo.owner;
            let is_external = true;
            try {
              await github.rest.orgs.checkMembershipForUser({ org, username });
              is_external = false;
            } catch (error) {
              if (error.status !== 404) throw error;
            }
            core.setOutput('is_external', is_external);

      - name: Set up Node.js
        if: ${{ steps.check_external.outputs.is_external == 'true' }}
        uses: actions/setup-node@v4
        with:
          node-version: '20'
          cache: 'npm'

      - name: Install dependencies
        if: ${{ steps.check_external.outputs.is_external == 'true' }}
        run: npm ci

      - name: Run tests
        if: ${{ steps.check_external.outputs.is_external == 'true' }}
        run: npm test
        env:
          CI: true
